import { chromium } from 'playwright';

const URL = 'http://localhost:6006/iframe.html?id=elements-zimmdrawer--x-large&viewMode=story';
const VIEWPORTS = [
  { name: '1920x1080', width: 1920, height: 1080 },
  { name: '1440x900', width: 1440, height: 900 },
  { name: '1000x800', width: 1000, height: 800 },
];

const browser = await chromium.launch();
const results = [];

for (const vp of VIEWPORTS) {
  const page = await browser.newPage({ viewport: { width: vp.width, height: vp.height } });
  page.on('pageerror', (e) => console.error(`[pageerror ${vp.name}]`, e.message));
  await page.goto(URL, { waitUntil: 'networkidle', timeout: 30000 });

  const dialog = page.getByRole('dialog');
  await dialog.waitFor({ state: 'visible', timeout: 15000 });

  const dialogBox = await dialog.boundingBox();
  const metrics = await page.evaluate(() => ({
    scrollWidth: document.documentElement.scrollWidth,
    innerWidth: window.innerWidth,
    clientWidthDoc: document.documentElement.clientWidth,
  }));
  const rectViaEval = await dialog.evaluate((el) => {
    const r = el.getBoundingClientRect();
    return { width: r.width, left: r.left, right: r.right };
  });

  results.push({
    viewport: vp.name,
    dialogBoundingBoxWidth: dialogBox ? dialogBox.width : null,
    dialogRectWidth: rectViaEval.width,
    dialogLeft: rectViaEval.left,
    dialogRight: rectViaEval.right,
    scrollWidth: metrics.scrollWidth,
    innerWidth: metrics.innerWidth,
    clientWidthDoc: metrics.clientWidthDoc,
  });

  await page.close();
}

await browser.close();
console.log(JSON.stringify(results, null, 2));
EOF
